/**
 * Arabic translations for the whole site (G9). ONE file: every English text that appears on the page and
 * its Arabic. Arabic text is marked "to be reviewed by the owner" (REVIEW_STATUS) until he approves it.
 *
 * How it is applied (src/i18n/translate.ts):
 *   1. EXACT: the whole text (whitespace-normalised) is looked up here.
 *   2. PATTERNS: texts with numbers, times, prices, models (e.g. "2,211 in stock", "Closes in 3h", "iPhone 15 Pro Screen").
 *   3. Texts joined with " · " are translated piece by piece.
 * Brand names, model names, part codes (SE-4544), units and e-mail/handles stay in Latin, as UAE shops write them.
 * To add a text: add a line to EXACT (or a pattern). To check coverage, run scripts/qa/i18n-check.mjs.
 */

