  'MEET SAMSOOM · PARTS ASSISTANT': 'تعرّف على سمسوم · مساعد القطع',
  'Ask at 3 a.m. Samsoom already knows the shelf.': 'اسأل في الثالثة فجراً. سمسوم يعرف الرف مسبقاً.',
  'Samsoom knows our catalogue, grades, hours and shipping. It finds the part, explains the grade, and hands you to a person on WhatsApp the second you need one.':
    'سمسوم يعرف كتالوجنا ودرجاتنا وساعات العمل والشحن. يجد القطعة، ويشرح الدرجة، ويحوّلك إلى شخص على واتساب في اللحظة التي تحتاجه.',
