  'Original or Service Pack for the best result, OLED for value, Incell when budget comes first.': 'أصلي أو سيرفس باك لأفضل نتيجة، وOLED للقيمة، وإنسل عندما تكون الميزانية أولاً.',
  'Original or Service Pack for the best result. OLED is great value. Incell when budget comes first. Every grade is labelled on your order.':
    'أصلي أو سيرفس باك لأفضل نتيجة. OLED قيمة ممتازة. إنسل عندما تكون الميزانية أولاً. كل درجة موسومة على طلبك.',
  'Yes. We ship every day to the Middle East, Africa, Europe and Asia. Tracked, packed by hand, quoted with your order.':
    'نعم. نشحن كل يوم إلى الشرق الأوسط وأفريقيا وأوروبا وآسيا. متتبَّع، مغلّف باليد، ومسعَّر مع طلبك.',
  'Yes. We ship worldwide, mainly to the Middle East, Africa, Europe and Asia. Tracked and securely packed; shipping is quoted with your order.':
    'نعم. نشحن لكل العالم، خاصة إلى الشرق الأوسط وأفريقيا وأوروبا وآسيا. متتبَّع ومغلّف بإحكام، ويُسعَّر الشحن مع طلبك.',
  'Our bench in Deira fixes screens, batteries, charging ports and board faults. Try the estimator for a price range.':
    'منضدتنا في ديرة تصلح الشاشات والبطاريات ومنافذ الشحن وأعطال اللوحة. جرّب المقدّر لمعرفة نطاق السعر.',
  'I didn’t catch that one. Try a model and part, like “A54 battery” or “iPhone 13 screen”, or ask about grades, hours or shipping.':
    'لم أفهم ذلك. جرّب موديلاً وقطعة، مثل «بطارية A54» أو «شاشة iPhone 13»، أو اسأل عن الدرجات أو ساعات العمل أو الشحن.',
