  'Your details, how we reach you, and your language.': 'بياناتك، وطريقة التواصل معك، ولغتك.',
  'Your repair tickets with their progress, and a warranty check for any order or repair.': 'تذاكر الإصلاح مع تقدّمها، وفحص الضمان لأي طلب أو إصلاح.',
  'Add the businesses you buy for: details, trade licence, TRN and every location. Orders can be placed for a company.': 'أضف الشركات التي تشتري لها: البيانات والرخصة التجارية والرقم الضريبي وكل فرع. يمكن تقديم الطلبات باسم شركة.',
  'Write to the team here: they answer from the Control Room during opening hours, and you get an e-mail when they do.': 'اكتب للفريق هنا: يردّون من غرفة التحكم في أوقات العمل، وتصلك رسالة بريد إلكتروني عند الرد.',
  'We will message you when the price drops or stock is back (e-mail alerts start when the database is connected).': 'سنراسلك عند انخفاض السعر أو عودة التوفر (تبدأ تنبيهات البريد عند ربط قاعدة البيانات).',
