  'Nothing you did caused this. Our team has been told automatically. You can try again, or tell us what you were doing so we fix it faster.': 'لم يحدث هذا بسببك. تم إبلاغ فريقنا تلقائياً. يمكنك المحاولة مجدداً، أو إخبارنا بما كنت تفعله لنصلحه أسرع.',
