  'Download my chats': 'نزّل محادثاتي',
  'Sure, let us find your order. I opened the order tracker below.': 'أكيد، لنجد طلبك. فتحت متتبع الطلبات بالأسفل.',
  'Happy to book you in. Pick the problem, a day and a time below.': 'يسعدني حجزك. اختر المشكلة واليوم والوقت بالأسفل.',
  'I can watch that for you. Find the part below and I will ring the bell when it is back.': 'سأراقبها لك. اعثر على القطعة بالأسفل وسأرنّ الجرس عند عودتها.',
