  'Shop commercial: screens, every grade, battery week, trade prices, worldwide shipping.': 'إعلان المتجر: شاشات، كل الجودات، أسبوع البطاريات، أسعار التجار، شحن لكل العالم.',
  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'الصندوق الكبير يعرض أحدث عروضنا. اختر تبويبًا أو قطعة أو ماركة ليعرض عروضها الخاصة.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'الوسم الملوّن هو الجودة (أصلي، OLED، Incell، AAA وغيرها). الوسم الداكن ذو الضوء هو المصنّع.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'ميّز القطعة بنجمة لتحفظها في My Bench. زر البطاقتين يضيفها للمقارنة: حتى ثلاث قطع جنبًا إلى جنب.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'رتّب حسب السعر أو الأحدث أو الأنسب، وبدّل بين الشبكة والقائمة.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'محلات الصيانة والتجار: قدّم مرة واحدة وكل قطعة تظهر سعرك التجاري.',
  'The questions people ask most, answered in one place. Still stuck? Ask Samsoom.': 'الأسئلة الأكثر شيوعًا مُجابة في مكان واحد. ما زلت محتارًا؟ اسأل سمسوم.',
