  "Original (Service Pack) is the part the brand fits. OLED Soft is close to original at a lower price. Incell is a reliable budget LCD. AAA is our best-price grade. Every part is labelled by quality and manufacturer.": "الأصلي (سيرفس باك) هو القطعة التي تركّبها الشركة نفسها. OLED Soft قريبة من الأصلي بسعر أقل. Incell شاشة LCD اقتصادية موثوقة. AAA هي درجتنا الأفضل سعراً. كل قطعة موسومة بالجودة والمصنّع.",
  "Original (Service Pack): 6 months. OLED Soft: 3 months. Incell and AAA: 1 month. Other parts: as stated on the product. The warranty starts on the invoice date.": "الأصلي (سيرفس باك): 6 أشهر. OLED Soft: 3 أشهر. Incell وAAA: شهر واحد. القطع الأخرى: كما هو مذكور على المنتج. يبدأ الضمان من تاريخ الفاتورة.",
