  "The card for everyone who buys parts or repairs with us. Register online, your first purchase activates it, and every dirham you spend charges it up.": "البطاقة لكل من يشتري القطع أو يصلح عندنا. سجّل أونلاين، أول عملية شراء تفعّلها، وكل درهم تنفقه يشحنها.",
  "The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.": "الأجرة تتبع سعر القطعة. قد يعدّلها الفني صعوداً أو نزولاً حسب القطعة والعمل، ويخبرك دائماً قبل البدء.",
  "The fine print,": "التفاصيل الدقيقة،",
  "The part and the fitting fee both count.": "القطعة وأجرة التركيب تُحتسبان معاً.",
  "The part the brand itself fits, in its service box. Same colors, brightness, touch and battery life as new. Our longest warranty.": "القطعة التي تركّبها الشركة نفسها، في علبة الصيانة. نفس الألوان والسطوع واللمس وعمر البطارية كالجديد. أطول ضمان لدينا.",
  "The part the brand itself fits.": "القطعة التي تركّبها الشركة نفسها.",
