  "The phones we stock parts for, and the factories behind every part, so you always know exactly what you are buying.": "الهواتف التي نوفّر قطعها، والمصانع وراء كل قطعة، لتعرف دائماً ما تشتريه بالضبط.",
  "The whole shop": "المتجر كله",
  "These terms are governed by the laws of the Emirate of Dubai and the federal laws of the UAE. The courts of Dubai have jurisdiction.": "تخضع هذه الشروط لقوانين إمارة دبي والقوانين الاتحادية لدولة الإمارات. وتختص محاكم دبي بالنظر فيها.",
  "This site keeps a few things in your browser so it works: your language, your cart, stars and recent searches, whether you have seen Samsoom’s tour, and your sign-in session. We do not use advertising cookies.": "يحفظ هذا الموقع بعض الأشياء في متصفحك ليعمل: لغتك، سلتك، النجوم وعمليات البحث الأخيرة، إن كنت شاهدت جولة سمسوم، وجلسة تسجيل دخولك. لا نستخدم ملفات تعريف إعلانية.",
  "Three steps to trade prices.": "ثلاث خطوات لأسعار الجملة.",
