  "Title": "العنوان",
  "To be the parts counter repair shops trust most, from Dubai to Madrid and beyond.": "أن نكون كاونتر القطع الأكثر ثقة لدى محلات الصيانة، من دبي إلى مدريد وما بعدهما.",
  "To sell and deliver parts, run repairs and warranties, approve trade accounts, answer you, keep the accounts required by UAE tax law, and improve the site. We do not sell your data.": "لبيع القطع وتوصيلها، وتشغيل الصيانة والضمانات، واعتماد حسابات الجملة، والرد عليك، والاحتفاظ بالسجلات التي يتطلبها قانون الضرائب الإماراتي، وتحسين الموقع. لا نبيع بياناتك.",
