  "Walk in any time we are open, or book a time and skip the queue. We confirm on WhatsApp.": "تعال أي وقت نكون مفتوحين، أو احجز موعداً وتجاوز الطابور. نؤكد على واتساب.",
  "Warranty & quality": "الضمان والجودة",
  "Warranty & returns": "الضمان والإرجاع",
  "Warranty covers faults from the part itself. It does not cover physical or water damage, or parts fitted elsewhere that were damaged while fitting.": "يغطي الضمان أعطال القطعة نفسها. لا يغطي الضرر الجسدي أو بالماء، أو القطع المركّبة في مكان آخر وتضررت أثناء التركيب.",
  "Warranty or return": "ضمان أو إرجاع",
  "Warranty policy": "سياسة الضمان",
  "We accept cash and card in the shop, bank transfer, and payment links we send after confirming your order. Orders are released for delivery or collection once paid, unless your trade account has approved credit.": "نقبل النقد والبطاقة في المحل، والتحويل البنكي، وروابط الدفع التي نرسلها بعد تأكيد طلبك. تُسلّم الطلبات للتوصيل أو الاستلام بعد الدفع، إلا إذا كان لحسابك التجاري ائتمان معتمد.",
  "We book the best route for your parcel: express for urgent parts, air cargo for bulk.": "نحجز أفضل مسار لطردك: السريع للقطع العاجلة، والشحن الجوي للكميات.",
  "We check the phone in front of you.": "نفحص الهاتف أمامك.",
  "We confirm on WhatsApp, then send a payment link": "نؤكد على واتساب، ثم نرسل رابط الدفع",
  "We help with packing and paperwork, but the shipping cost and the shipper’s terms are between you and your shipper.": "نساعد في التغليف والأوراق، لكن تكلفة الشحن وشروط شركة الشحن بينك وبينها.",
  "We hire people who like phones, people and getting things exactly right. Openings are samples until the owner publishes real ones.": "نوظف من يحبون الهواتف والناس والدقة. الوظائف تجريبية حتى ينشر المالك الوظائف الحقيقية.",
  "We opened WhatsApp with your booking; the team confirms the time there.": "فتحنا واتساب بحجزك؛ الفريق يؤكد الموعد هناك.",
  "We opened WhatsApp with your request; the team replies there.": "فتحنا واتساب بطلبك؛ الفريق يرد هناك.",
  "We quote shipping": "نسعّر الشحن",
  "We received your application and will be in touch.": "استلمنا طلبك وسنتواصل معك.",
  "We received your order. Our team confirms stock, delivery and the final price on WhatsApp, usually within minutes during opening hours.": "استلمنا طلبك. يؤكد فريقنا التوفر والتوصيل والسعر النهائي على واتساب، عادة خلال دقائق في ساعات العمل.",
  "We reply here during opening hours, and by e-mail after.": "نرد هنا في ساعات العمل، وبالبريد بعدها.",
  "We sent a 6-digit code to": "أرسلنا رمزاً من 6 أرقام إلى",
  "We ship door to door with our partners (such as Sky Dragon, Emirates SkyCargo, UPS and DHL) and quote the price and time before you pay. Duties and taxes in the destination country are paid by the receiver unless agreed otherwise.": "نشحن من الباب للباب مع شركائنا (مثل Sky Dragon وEmirates SkyCargo وUPS وDHL) ونعطيك السعر والمدة قبل الدفع. الرسوم والضرائب في بلد الوصول يدفعها المستلم ما لم يُتفق على غير ذلك.",
  "We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.": "نشحن القطع كل أسبوع لمحلات الصيانة والتجار في الشرق الأوسط وأفريقيا وأوروبا وآسيا: من الباب للباب مع شركائنا، أو مع شركة الشحن الخاصة بك.",
  "We ship to 28+ countries every week, door to door, and we can hand your order to your own shipper.": "نشحن إلى أكثر من 28 دولة كل أسبوع، من الباب للباب، ونستطيع تسليم طلبك لشركة الشحن الخاصة بك.",
  "We started in 2003 as Syria Tell. In 2020 the shop took the name Sam Electronics, with the same management and the same people behind the counter.": "بدأنا عام 2003 باسم سوريا تل. وفي 2020 أخذ المحل اسم سام للإلكترونيات، بنفس الإدارة ونفس الأشخاص خلف الكاونتر.",
  "We verify and approve": "نتحقق ونوافق",
  "We will confirm it is you by e-mail, then act on it.": "سنتأكد أنه أنت عبر البريد، ثم ننفّذ.",
