  "Yes. A repair shop owner can hold a Sam Grid card for the business and a Sam Circuit card for personal purchases. Both show in My Bench.": "نعم. يمكن لصاحب محل الصيانة حمل بطاقة Sam Grid للمحل وبطاقة Sam Circuit لمشترياته الشخصية. وتظهر الاثنتان في My Bench.",
