  "You may return an unused part, in its original packaging with labels and protective films intact, within 7 days of purchase for an exchange or store credit. Screens with removed films are considered used.": "يمكنك إرجاع قطعة غير مستعملة في علبتها الأصلية بملصقاتها وأغشيتها الواقية سليمة خلال 7 أيام من الشراء، مقابل استبدال أو رصيد في المحل. الشاشات المنزوعة أغشيتها تُعد مستعملة.",
