  "AED 1 = 1 point on every part and repair. Your level rises as your points do.": "كل 1 درهم = نقطة على كل قطعة وإصلاح. يرتفع مستواك مع نقاطك.",
  "The trade card. Apply online with your trade licence; our management team checks it and activates the card by hand. Your monthly volume sets your level.": "بطاقة التجار. قدّم أونلاين برخصتك التجارية؛ يراجعها فريق الإدارة ويفعّل البطاقة يدوياً. حجم مشترياتك الشهري يحدد مستواك.",
