  "Yes: the part and the fitting fee both count, AED 1 = 1 point.": "نعم: القطعة وأجرة التركيب تُحتسبان معاً، كل 1 درهم = نقطة.",
  "From your approved trade orders in the last 30 days. It is reviewed every month; you never drop more than one level at a time.": "من طلبات الجملة المعتمدة خلال آخر 30 يوماً. يُراجع كل شهر، ولا تنزل أكثر من مستوى واحد في كل مرة.",
