  "Prices in the shop are shown without VAT; 5% UAE VAT is added at checkout and shown on your invoice.": "الأسعار في المتجر بدون ضريبة؛ تُضاف ضريبة القيمة المضافة 5% عند الدفع وتظهر في فاتورتك.",
  "Bring or send it back with the invoice within the warranty. We test it; if it is faulty we replace it or refund you. See the returns policy for the details.": "أحضرها أو أرسلها مع الفاتورة خلال فترة الضمان. نفحصها؛ وإن كانت معيبة نستبدلها أو نعيد لك المبلغ. راجع سياسة الإرجاع للتفاصيل.",
  "Cookies": "ملفات تعريف الارتباط",
  "These terms apply to every sale by Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates (\"Sam Electronics\", \"we\"), in the shop, on this website, on WhatsApp or by phone.": "تنطبق هذه الشروط على كل عملية بيع من سام للإلكترونيات ذ.م.م، المرر، ديرة، دبي، الإمارات العربية المتحدة («سام للإلكترونيات»، «نحن»)، في المحل أو على هذا الموقع أو على واتساب أو بالهاتف.",
  "Prices": "الأسعار",
  "Prices are in UAE dirhams (AED). Prices shown in the shop do not include VAT; 5% UAE VAT is added at checkout and shown on the tax invoice.": "الأسعار بالدرهم الإماراتي (AED). الأسعار المعروضة في المتجر لا تشمل الضريبة؛ تُضاف ضريبة 5% عند الدفع وتظهر في الفاتورة الضريبية.",
  "Orders": "الطلبات",
  "Liability": "المسؤولية",
  "Refunds": "استرداد المبالغ",
  "You may ask us to hand your order to your own shipper or cargo agent. We pack it and share the paperwork; the shipping cost and the shipper’s terms are between you and your shipper, and responsibility passes to you when we hand the parcel over.": "يمكنك أن تطلب تسليم طلبك لشركة الشحن أو وكيل الشحن الخاص بك. نغلّفه ونشارك الأوراق؛ تكلفة الشحن وشروط الشركة بينك وبينها، وتنتقل المسؤولية إليك عند تسليم الطرد.",
  "You can clear them at any time in your browser; the site will simply forget your cart and preferences on that device.": "يمكنك مسحها في أي وقت من متصفحك؛ سينسى الموقع سلتك وتفضيلاتك على ذلك الجهاز فقط.",
