  "We named our cookies after phone parts, so you can see what each one does at a glance. Only the Battery is always on.": "سمّينا ملفات تعريف الارتباط بأسماء قطع الهاتف، لترى ما يفعله كل منها بنظرة. البطارية فقط تعمل دائماً.",
