  "Currency, sounds, recent searches, starred parts and your devices.": "العملة والأصوات وعمليات البحث الأخيرة والقطع المميزة بنجمة وأجهزتك.",
  "Which pages are opened and how fast they load. Never your name or contact.": "الصفحات التي تُفتح وسرعة تحميلها. لا اسمك ولا بيانات تواصلك أبداً.",
  "The kinds of parts you look at, to show matching offers.": "أنواع القطع التي تشاهدها، لعرض عروض تناسبها.",
  "Until you clear them (sign-in: until you sign out).": "حتى تمسحها (الدخول: حتى تسجّل الخروج).",
  "12 months, or until you clear them.": "12 شهراً، أو حتى تمسحها.",
  "13 months.": "13 شهراً.",
  "6 months.": "6 أشهر.",
  "Without them the cart would empty and the site would forget your language on every page.": "بدونها تفرغ السلة وينسى الموقع لغتك في كل صفحة.",
  "So you do not have to set things up again on every visit.": "حتى لا تعيد الإعداد في كل زيارة.",
  "To see which pages are slow or confusing and fix them.": "لنعرف أي الصفحات بطيئة أو مربكة ونصلحها.",
  "So the offers you see are for your phones, not random ones.": "لتكون العروض التي تراها لهواتفك، لا عشوائية.",
  "You add a screen to the cart, open another page, and it is still there.": "تضيف شاشة إلى السلة، تفتح صفحة أخرى، وتبقى موجودة.",
  "You searched \"A54 battery\" yesterday; today it is first in your recent searches.": "بحثت أمس عن «بطارية A54»؛ اليوم تظهر أولاً في عمليات بحثك الأخيرة.",
  "We notice the Repair page loads slowly on phones and make it faster.": "نلاحظ أن صفحة الصيانة بطيئة على الهواتف فنجعلها أسرع.",
  "You look at iPhone 13 screens; the next deal we show you is for that screen.": "تشاهد شاشات iPhone 13؛ العرض التالي الذي نريك إياه لتلك الشاشة.",
