  "Thanks for the photo! I can’t look at photos right now, so send it to the team on WhatsApp and they will tell you the part and the price.": "شكراً على الصورة! لا أستطيع رؤية الصور الآن، فأرسلها إلى الفريق على واتساب وسيخبرونك بالقطعة والسعر.",
  "Thanks for the photo! Send it to the team on WhatsApp and they will tell you the part and the price.": "شكراً على الصورة! أرسلها إلى الفريق على واتساب وسيخبرونك بالقطعة والسعر.",
